    anchor = 'for marker in (\n    "SubtitleModeButton", "BlurModeButton", "AudioModeButton", "ExportModeButton",\n'
    guard = '''for forbidden in (\n    "SubtitleModeButton.Click +=", "BlurModeButton.Click +=", "AudioModeButton.Click +=", "ExportModeButton.Click +=",\n    "OpenVideoButton.Click +=", "RenderButton.Click -=", "RenderButton.IsEnabledChanged +=",\n    "OnNavigatedTo(", "Render_Click(sender, e)", "EditorParity_Loaded", "HookEditorLivePreviewEvents",\n):\n    require(forbidden not in editor_partials, f"Editor cleanup regression reintroduced {forbidden}")\nrequire("EnsureEditorParityInitialized();" in editor_partials and "EnsureImageFeatureInitialized();" in editor_partials,\n        "Editor must initialize parity and image tools from one lifecycle owner")\n\n'''
    if anchor not in validator:
        raise RuntimeError("missing editor validator anchor")
    validator = validator.replace(anchor, guard + anchor, 1)
    write(VALIDATOR, validator)

    print("Applied CORE-01..CORE-11 Editor cleanup transformations")
    return 0


